for i,n in by.items():
    elig = n['status']=='active' and n['confirmation_status']=='confirmed' and n['evaluation_status']=='pass' and (n.get('implementation_readiness') or {}).get('status')=='complete' and all(d in done for d in n.get('depends_on',[]))
    if elig and i not in ready: fails.append(('IN1b',i,'eligible but missing'))
    if not elig and i in ready: fails.append(('IN1b',i,'ineligible but present'))
